-- Outbound webhook subscriptions for geofence events. A subscription selects
-- the event types it wants and optionally one geofence. The signing secret is
-- generated by the gateway and shown once; it is stored so deliveries can be
-- signed and is never returned by a read endpoint.
CREATE TABLE event_subscription (
    subscription_id UUID PRIMARY KEY,
    tenant_id       BIGINT NOT NULL REFERENCES tenant (tenant_id),
    name            VARCHAR(128) NOT NULL,
    url             VARCHAR(1024) NOT NULL,
    secret          VARCHAR(128) NOT NULL,
    event_types     TEXT[] NOT NULL CHECK (array_length(event_types, 1) BETWEEN 1 AND 3),
    geofence_id     UUID REFERENCES geofence (geofence_id) ON DELETE CASCADE,
    enabled         BOOLEAN NOT NULL DEFAULT TRUE,
    created_by      UUID REFERENCES ops_user (user_id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, name)
);

CREATE INDEX event_subscription_tenant ON event_subscription (tenant_id, enabled);

-- One row per (subscription, event). The unique key makes a repeated enqueue a
-- no-op, so re-evaluating a stored result cannot send its event twice.
CREATE TABLE webhook_delivery (
    delivery_id     BIGSERIAL PRIMARY KEY,
    tenant_id       BIGINT NOT NULL REFERENCES tenant (tenant_id),
    subscription_id UUID NOT NULL REFERENCES event_subscription (subscription_id)
                        ON DELETE CASCADE,
    event_id        BIGINT NOT NULL REFERENCES geofence_event (event_id) ON DELETE CASCADE,
    status          VARCHAR(16) NOT NULL CHECK (status IN ('PENDING', 'DELIVERED', 'FAILED')),
    attempts        INTEGER NOT NULL DEFAULT 0,
    next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_status_code INTEGER,
    last_error      VARCHAR(256),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    delivered_at    TIMESTAMPTZ,
    UNIQUE (subscription_id, event_id)
);

CREATE INDEX webhook_delivery_due ON webhook_delivery (status, next_attempt_at);
CREATE INDEX webhook_delivery_subscription ON webhook_delivery (subscription_id, created_at DESC);
